INSERT OR REPLACE INTO news ("id","title","title_en","summary","summary_en","body","body_en","image","published","published_at","created_at","updated_at") VALUES ('editorial-portfolio','Портфолио начинается с вас','Your portfolio starts with you','Простые фотографии, естественный свет и ваша индивидуальность. Что нужно для первого знакомства с агентством.','Simple photographs, natural light and your individuality. Everything you need for your first agency introduction.','Для заявки не нужна профессиональная съемка. Подготовьте портрет анфас, профиль и фотографию в полный рост. Выберите однотонную одежду, естественный свет и спокойный фон. Не используйте фильтры и сильную ретушь. В анкете укажите актуальные параметры и контакты, по которым с вами удобно связаться.','You do not need a professional shoot to apply. Prepare a front portrait, a profile photograph and a full-length shot. Choose simple clothes, natural light and a neutral background. Avoid filters and heavy retouching. Include current measurements and contact details.','/images/woman-04.jpg',1,'2026-11-01','2026-11-13T16:45:47.610Z','2026-11-13T16:45:47.610Z');
INSERT OR REPLACE INTO news ("id","title","title_en","summary","summary_en","body","body_en","image","published","published_at","created_at","updated_at") VALUES ('editorial-first-shoot','Перед первой съемкой','Before your first shoot','Как подготовиться к встрече с командой и чувствовать себя свободнее перед камерой.','How to prepare for a creative team and feel more comfortable in front of the camera.','Заранее уточните время, место и задачу съемки. Сохраните контакты координатора, подготовьте базовую одежду по списку команды и оставьте время на дорогу. Если у вас есть вопросы, задавайте их до съемки. Хороший результат начинается с понятной коммуникации и взаимного уважения.','Confirm the time, place and brief in advance. Save the coordinator’s contact, prepare any requested basics and allow time to travel. Ask questions before the shoot. Strong work starts with clear communication and mutual respect.','/images/man-04.jpg',1,'2026-10-28','2026-11-13T16:45:47.610Z','2026-11-13T16:45:47.610Z');
INSERT OR REPLACE INTO settings ("key","value") VALUES ('agency','{"name":"FORMA","descriptor":"MODEL MANAGEMENT","city":"Москва","city_en":"Moscow","email":"hello@forma.agency","phone":"","telegram":"","instagram":"","vk":"","tagline":"Лица, которые запоминают.","tagline_en":"Faces you remember.","about":"Мы видим характер за внешностью. FORMA — пространство для новых лиц, сильных индивидуальностей и творческого сотрудничества. Мы соединяем моделей и команды, которым близок внимательный, современный взгляд на моду.","about_en":"We see the character behind the face. FORMA is a space for new talent, strong personalities and creative collaborations. We connect models with teams that share a thoughtful, contemporary perspective on fashion.","seo_title":"FORMA — модельное агентство","seo_description":"Модели, новые лица и творческое сотрудничество. Каталог и заявки в модельное агентство FORMA.","hero_image":"/images/woman-02.jpg","hero_secondary":"/images/man-04.jpg","demo_mode":true}');
INSERT OR REPLACE INTO settings ("key","value") VALUES ('initialized','1');
